template:
fn select_matching<F>(
    items: &[i32],
    ⟦param_decl⟧,
) -> Vec<i32>
where
    F: ⟦bound_spec⟧,
{
    items
        .iter()
        .copied()
        .filter(|&x| predicate(x))
        .collect()
}

fn main() {
    let limit = 10;
    let result = select_matching(
        &[5, 12, 8, 15],
        |x| x < limit,
    );
    println!("{:?}", result);
}

tests:
#[test]
fn filters_items() {
    let limit = 10;
    let res = select_matching(&[3, 15, 8, 20], |x| x < limit);
    assert_eq!(res, vec![3, 8]);
}
